"use client";

import { motion } from "framer-motion";
import Button from "@/components/ui/Button";

export default function About() {
  return (
    <section
      id="about"
      className="mx-auto flex min-h-[90vh] max-w-7xl items-center px-6 py-24 transition-colors duration-300 lg:px-8"
    >
      <div className="grid w-full items-center gap-16 lg:grid-cols-2">
        {/* Left - Profile Card */}
        <motion.div
          initial={{ opacity: 0, x: -60 }}
          whileInView={{ opacity: 1, x: 0 }}
          viewport={{ once: true, amount: 0.2 }}
          transition={{ duration: 0.7 }}
          className="flex justify-center"
        >
          <div className="relative">
            {/* Glow */}
            <div className="absolute -inset-3 rounded-[40px] bg-gradient-to-r from-blue-500 to-cyan-400 opacity-20 blur-2xl" />

            {/* Card */}
            <div className="relative flex h-[420px] w-[340px] items-center justify-center rounded-[40px] border border-zinc-200 bg-gradient-to-br from-slate-50 to-blue-50 shadow-2xl transition-colors duration-300 dark:border-zinc-700 dark:from-zinc-900 dark:to-zinc-950">
              <div className="flex h-40 w-40 items-center justify-center rounded-full bg-blue-600 text-5xl font-black text-white shadow-xl shadow-blue-500/20">
                DK
              </div>
            </div>
          </div>
        </motion.div>

        {/* Right - About Content */}
        <motion.div
          initial={{ opacity: 0, x: 60 }}
          whileInView={{ opacity: 1, x: 0 }}
          viewport={{ once: true, amount: 0.2 }}
          transition={{ duration: 0.7 }}
        >
          {/* Section Label */}
          <span className="inline-flex rounded-full bg-blue-100 px-4 py-2 text-sm font-semibold text-blue-700 dark:bg-blue-950/50 dark:text-blue-400">
            ABOUT ME
          </span>

          {/* Heading */}
          <h2 className="mt-5 text-4xl font-black leading-tight tracking-tight text-zinc-900 dark:text-white md:text-5xl">
            Building AI Solutions
            <span className="block text-blue-600 dark:text-blue-400">
              That Solve Real Problems
            </span>
          </h2>

          {/* Description */}
          <p className="mt-7 max-w-2xl text-base leading-8 text-zinc-600 dark:text-zinc-400 md:text-lg">
            I'm an AI Engineer and Java Full Stack Developer passionate about
            building scalable software, AI-powered applications, enterprise
            RAG systems, computer vision solutions, and modern web platforms.
          </p>

          <p className="mt-5 max-w-2xl text-base leading-8 text-zinc-600 dark:text-zinc-400 md:text-lg">
            My goal is to combine software engineering with artificial
            intelligence to create production-ready products that deliver
            measurable business value.
          </p>

          {/* Focus Areas */}
          <div className="mt-8 grid grid-cols-2 gap-4">
            {/* AI */}
            <div className="rounded-2xl border border-zinc-200 bg-white p-5 shadow-sm transition-all duration-300 hover:-translate-y-1 hover:shadow-md dark:border-zinc-700 dark:bg-zinc-900">
              <h3 className="text-2xl font-bold text-blue-600 dark:text-blue-400">
                AI
              </h3>
              <p className="mt-1 text-sm text-zinc-500 dark:text-zinc-400">
                Engineering
              </p>
            </div>

            {/* Java */}
            <div className="rounded-2xl border border-zinc-200 bg-white p-5 shadow-sm transition-all duration-300 hover:-translate-y-1 hover:shadow-md dark:border-zinc-700 dark:bg-zinc-900">
              <h3 className="text-2xl font-bold text-blue-600 dark:text-blue-400">
                Java
              </h3>
              <p className="mt-1 text-sm text-zinc-500 dark:text-zinc-400">
                Backend
              </p>
            </div>

            {/* React */}
            <div className="rounded-2xl border border-zinc-200 bg-white p-5 shadow-sm transition-all duration-300 hover:-translate-y-1 hover:shadow-md dark:border-zinc-700 dark:bg-zinc-900">
              <h3 className="text-2xl font-bold text-blue-600 dark:text-blue-400">
                React
              </h3>
              <p className="mt-1 text-sm text-zinc-500 dark:text-zinc-400">
                Frontend
              </p>
            </div>

            {/* Cloud */}
            <div className="rounded-2xl border border-zinc-200 bg-white p-5 shadow-sm transition-all duration-300 hover:-translate-y-1 hover:shadow-md dark:border-zinc-700 dark:bg-zinc-900">
              <h3 className="text-2xl font-bold text-blue-600 dark:text-blue-400">
                Cloud
              </h3>
              <p className="mt-1 text-sm text-zinc-500 dark:text-zinc-400">
                Deployment
              </p>
            </div>
          </div>

          {/* Resume */}
          <div className="mt-8">
            <Button>Download Resume</Button>
          </div>
        </motion.div>
      </div>
    </section>
  );
}