"use client";

import { motion } from "framer-motion";
import {
  FaGithub,
  FaLinkedin,
  FaJava,
  FaReact,
  FaDocker,
  FaPython,
} from "react-icons/fa";
import { SiSpringboot } from "react-icons/si";

import Button from "@/components/ui/Button";

const technologies = [
  { icon: <FaPython />, name: "Python" },
  { icon: <FaJava />, name: "Java" },
  { icon: <SiSpringboot />, name: "Spring Boot" },
  { icon: <FaReact />, name: "React" },
  { icon: <FaDocker />, name: "Docker" },
];

export default function Hero() {
  return (
    <section
      id="home"
      className="mx-auto grid min-h-screen max-w-7xl items-center gap-16 px-6 pb-20 pt-32 md:px-10 lg:grid-cols-2 lg:gap-20"
    >
      {/* Left */}
      <motion.div
        initial={{ opacity: 0, x: -40 }}
        animate={{ opacity: 1, x: 0 }}
        transition={{ duration: 0.7 }}
        className="max-w-2xl"
      >
        <span className="inline-flex rounded-full bg-blue-100 px-4 py-2 text-sm font-semibold text-blue-700 dark:bg-blue-950 dark:text-blue-400">
          👋 Welcome to my portfolio
        </span>

        <h1 className="mt-6 text-4xl font-extrabold leading-tight tracking-tight text-zinc-900 dark:text-white sm:text-5xl md:text-6xl">
          Building
          <span className="block text-blue-600 dark:text-blue-400">
            Intelligent Software
          </span>
        </h1>

        <h2 className="mt-5 text-lg font-semibold text-zinc-700 dark:text-zinc-300 md:text-xl">
          AI Engineer • Java Full Stack Developer
        </h2>

        <p className="mt-6 max-w-xl text-base leading-8 text-zinc-600 dark:text-zinc-400 md:text-lg">
          I design and build production-ready AI solutions using Generative
          AI, LLMs, RAG, Computer Vision, Java Spring Boot, React, Docker, and
          modern cloud technologies to solve real business problems.
        </p>

        {/* Buttons */}
        <div className="mt-8 flex flex-wrap items-center gap-4">
          <Button className="px-7 py-3 text-base shadow-lg shadow-blue-500/20">
            Hire Me
          </Button>

          <Button variant="secondary" className="px-7 py-3 text-base">
            View Projects
          </Button>
        </div>

        {/* Social Links */}
        <div className="mt-8 flex items-center gap-5 text-2xl text-zinc-500 dark:text-zinc-400">
          <a
            href="https://github.com/deepak-sjd"
            target="_blank"
            rel="noreferrer"
            aria-label="GitHub"
            className="transition hover:scale-110 hover:text-zinc-900 dark:hover:text-white"
          >
            <FaGithub />
          </a>

          <a
            href="https://linkedin.com/in/deepak-sjd"
            target="_blank"
            rel="noreferrer"
            aria-label="LinkedIn"
            className="transition hover:scale-110 hover:text-blue-600"
          >
            <FaLinkedin />
          </a>
        </div>

        {/* Technologies */}
        <div className="mt-10 flex flex-wrap gap-3">
          {technologies.map((tech) => (
            <div
              key={tech.name}
              className="flex items-center gap-2 rounded-xl border border-zinc-200 bg-white px-3 py-2.5 shadow-sm transition-all duration-300 hover:-translate-y-1 hover:shadow-md dark:border-zinc-700 dark:bg-zinc-900"
            >
              <span className="text-lg text-blue-600">{tech.icon}</span>

              <span className="text-sm font-medium text-zinc-800 dark:text-zinc-200">
                {tech.name}
              </span>
            </div>
          ))}
        </div>
      </motion.div>

      {/* Right */}
      <motion.div
        initial={{ opacity: 0, x: 40 }}
        animate={{ opacity: 1, x: 0 }}
        transition={{ duration: 0.7, delay: 0.2 }}
        className="flex justify-center lg:justify-end"
      >
        <div className="flex h-[430px] w-full max-w-[380px] flex-col items-center justify-center rounded-[36px] border border-zinc-200 bg-gradient-to-br from-blue-50 via-white to-indigo-100 shadow-xl transition-colors duration-300 dark:border-zinc-700 dark:from-zinc-900 dark:via-zinc-950 dark:to-zinc-900">
          <div className="mb-5 flex h-32 w-32 items-center justify-center rounded-full bg-blue-600 text-5xl font-bold text-white shadow-lg">
            DK
          </div>

          <h3 className="text-2xl font-bold text-zinc-900 dark:text-white">
            Deepak Kumar
          </h3>

          <p className="mt-2 text-sm text-zinc-500 dark:text-zinc-400">
            AI Engineer
          </p>

          <div className="mt-8 grid grid-cols-2 gap-4">
            <div className="rounded-2xl bg-white px-6 py-4 text-center shadow-sm dark:bg-zinc-900">
              <h4 className="text-2xl font-bold text-blue-600">10+</h4>

              <p className="mt-1 text-xs text-zinc-500 dark:text-zinc-400">
                Technologies
              </p>
            </div>

            <div className="rounded-2xl bg-white px-6 py-4 text-center shadow-sm dark:bg-zinc-900">
              <h4 className="text-2xl font-bold text-blue-600">AI</h4>

              <p className="mt-1 text-xs text-zinc-500 dark:text-zinc-400">
                Focused
              </p>
            </div>
          </div>
        </div>
      </motion.div>
    </section>
  );
}