"use client";

import { motion } from "framer-motion";
import { FaExternalLinkAlt, FaGithub } from "react-icons/fa";

const projects = [
  {
    title: "Enterprise RAG System",
    description:
      "Production-ready Retrieval-Augmented Generation platform with semantic search, vector database and LLM-powered document assistant.",
    technologies: [
      "Python",
      "LangChain",
      "LLM",
      "RAG",
      "Docker",
      "Milvus",
    ],
    github: "#",
    demo: "#",
  },
  {
    title: "Smart Manufacturing Time Study AI",
    description:
      "AI-powered activity recognition system for manufacturing productivity analysis using computer vision and timeline generation.",
    technologies: [
      "Python",
      "OpenCV",
      "PyTorch",
      "VideoMAE",
      "FastAPI",
    ],
    github: "#",
    demo: "#",
  },
  {
    title: "AI Fault Investigation Assistant",
    description:
      "Enterprise AI assistant that analyzes machine failures using RAG, LLMs and engineering documentation.",
    technologies: [
      "Python",
      "RAG",
      "LLM",
      "FastAPI",
      "Vector DB",
    ],
    github: "#",
    demo: "#",
  },
];

export default function Projects() {
  return (
    <section
      id="projects"
      className="bg-white px-6 py-24 transition-colors duration-300 dark:bg-zinc-950 lg:px-8"
    >
      <div className="mx-auto max-w-7xl">
        {/* Section Header */}
        <motion.div
          initial={{ opacity: 0, y: 40 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true, amount: 0.2 }}
          transition={{ duration: 0.7 }}
          className="text-center"
        >
          <span className="inline-flex rounded-full bg-blue-100 px-4 py-2 text-sm font-semibold text-blue-700 dark:bg-blue-950/50 dark:text-blue-400">
            FEATURED PROJECTS
          </span>

          <h2 className="mt-5 text-4xl font-black tracking-tight text-zinc-900 dark:text-white md:text-5xl">
            Things I've Built
          </h2>

          <p className="mx-auto mt-5 max-w-3xl text-base leading-8 text-zinc-600 dark:text-zinc-400 md:text-lg">
            Production-ready AI applications, backend systems and enterprise
            software focused on solving real business problems.
          </p>
        </motion.div>

        {/* Project Cards */}
        <div className="mt-14 grid gap-8 lg:grid-cols-3">
          {projects.map((project, index) => (
            <motion.article
              key={project.title}
              initial={{ opacity: 0, y: 40 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true, amount: 0.2 }}
              transition={{
                duration: 0.5,
                delay: index * 0.1,
              }}
              whileHover={{ y: -8 }}
              className="overflow-hidden rounded-3xl border border-zinc-200 bg-white shadow-lg transition-all duration-300 hover:shadow-2xl dark:border-zinc-700 dark:bg-zinc-900"
            >
              {/* Project Preview */}
              <div className="flex h-48 items-center justify-center bg-gradient-to-br from-blue-600 via-indigo-500 to-cyan-500">
                <span className="text-5xl font-black text-white/20">
                  {String(index + 1).padStart(2, "0")}
                </span>
              </div>

              {/* Project Content */}
              <div className="p-7">
                <h3 className="text-xl font-bold text-zinc-900 dark:text-white md:text-2xl">
                  {project.title}
                </h3>

                <p className="mt-4 text-base leading-7 text-zinc-600 dark:text-zinc-400">
                  {project.description}
                </p>

                {/* Technologies */}
                <div className="mt-6 flex flex-wrap gap-2">
                  {project.technologies.map((tech) => (
                    <span
                      key={tech}
                      className="rounded-full bg-slate-100 px-3 py-1.5 text-sm font-medium text-zinc-700 dark:bg-zinc-800 dark:text-zinc-300"
                    >
                      {tech}
                    </span>
                  ))}
                </div>

                {/* Links */}
                <div className="mt-7 flex flex-wrap gap-3">
                  <a
                    href={project.github}
                    className="flex items-center gap-2 rounded-xl border border-zinc-300 px-4 py-2.5 text-sm font-semibold text-zinc-800 transition hover:bg-zinc-100 dark:border-zinc-700 dark:text-zinc-200 dark:hover:bg-zinc-800"
                  >
                    <FaGithub />
                    GitHub
                  </a>

                  <a
                    href={project.demo}
                    className="flex items-center gap-2 rounded-xl bg-blue-600 px-4 py-2.5 text-sm font-semibold text-white transition hover:bg-blue-700"
                  >
                    <FaExternalLinkAlt />
                    Demo
                  </a>
                </div>
              </div>
            </motion.article>
          ))}
        </div>
      </div>
    </section>
  );
}