"use client";

import { motion } from "framer-motion";
import {
  FaEnvelope,
  FaPhone,
  FaMapMarkerAlt,
  FaGithub,
  FaLinkedin,
} from "react-icons/fa";

import Button from "@/components/ui/Button";

export default function Contact() {
  return (
    <section
      id="contact"
      className="border-t border-zinc-200 bg-white py-24 transition-colors duration-300 dark:border-zinc-800 dark:bg-zinc-950"
    >
      <div className="mx-auto max-w-7xl px-6 lg:px-8">

        {/* Heading */}
        <motion.div
          initial={{ opacity: 0, y: 40 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.6 }}
          className="text-center"
        >
          <span className="rounded-full bg-blue-100 px-4 py-2 text-sm font-semibold text-blue-700 dark:bg-blue-950 dark:text-blue-400">
            CONTACT
          </span>

          <h2 className="mt-6 text-4xl font-black text-zinc-900 dark:text-white md:text-5xl">
            Let's Build Something Amazing
          </h2>

          <p className="mx-auto mt-6 max-w-3xl text-base leading-8 text-zinc-600 dark:text-zinc-400 md:text-lg">
            Interested in AI, Full Stack Development, or collaborating on
            innovative software solutions? Feel free to reach out.
          </p>
        </motion.div>

        {/* Content */}
        <div className="mt-16 grid gap-12 lg:grid-cols-2">

          {/* Left */}
          <motion.div
            initial={{ opacity: 0, x: -40 }}
            whileInView={{ opacity: 1, x: 0 }}
            viewport={{ once: true }}
            transition={{ duration: 0.6 }}
            className="space-y-6"
          >
            {/* Email */}
            <div className="rounded-3xl border border-zinc-200 bg-white p-7 shadow-sm transition-colors duration-300 dark:border-zinc-800 dark:bg-zinc-900">
              <div className="flex items-center gap-4">
                <FaEnvelope className="text-2xl text-blue-600" />

                <div>
                  <h3 className="font-semibold text-zinc-900 dark:text-white">
                    Email
                  </h3>

                  <p className="mt-1 text-zinc-600 dark:text-zinc-400">
                    deepak@example.com
                  </p>
                </div>
              </div>
            </div>

            {/* Phone */}
            <div className="rounded-3xl border border-zinc-200 bg-white p-7 shadow-sm transition-colors duration-300 dark:border-zinc-800 dark:bg-zinc-900">
              <div className="flex items-center gap-4">
                <FaPhone className="text-2xl text-blue-600" />

                <div>
                  <h3 className="font-semibold text-zinc-900 dark:text-white">
                    Phone
                  </h3>

                  <p className="mt-1 text-zinc-600 dark:text-zinc-400">
                    +91 74795 19511
                  </p>
                </div>
              </div>
            </div>

            {/* Location */}
            <div className="rounded-3xl border border-zinc-200 bg-white p-7 shadow-sm transition-colors duration-300 dark:border-zinc-800 dark:bg-zinc-900">
              <div className="flex items-center gap-4">
                <FaMapMarkerAlt className="text-2xl text-blue-600" />

                <div>
                  <h3 className="font-semibold text-zinc-900 dark:text-white">
                    Location
                  </h3>

                  <p className="mt-1 text-zinc-600 dark:text-zinc-400">
                    Chennai, Tamil Nadu, India
                  </p>
                </div>
              </div>
            </div>

            {/* Social Links */}
            <div className="flex gap-5 pt-2 text-3xl">
              <a
                href="https://github.com/deepak-sjd"
                target="_blank"
                rel="noreferrer"
                aria-label="GitHub"
                className="text-zinc-600 transition hover:text-blue-600 dark:text-zinc-400 dark:hover:text-blue-400"
              >
                <FaGithub />
              </a>

              <a
                href="https://linkedin.com/in/deepak-sjd"
                target="_blank"
                rel="noreferrer"
                aria-label="LinkedIn"
                className="text-zinc-600 transition hover:text-blue-600 dark:text-zinc-400 dark:hover:text-blue-400"
              >
                <FaLinkedin />
              </a>
            </div>
          </motion.div>

          {/* Right */}
          <motion.div
            initial={{ opacity: 0, x: 40 }}
            whileInView={{ opacity: 1, x: 0 }}
            viewport={{ once: true }}
            transition={{ duration: 0.6 }}
          >
            <form className="space-y-6 rounded-3xl border border-zinc-200 bg-white p-8 shadow-lg transition-colors duration-300 dark:border-zinc-800 dark:bg-zinc-900 md:p-10">

              <input
                type="text"
                placeholder="Full Name"
                className="w-full rounded-xl border border-zinc-300 bg-white px-5 py-4 text-zinc-900 outline-none transition placeholder:text-zinc-400 focus:border-blue-600 dark:border-zinc-700 dark:bg-zinc-950 dark:text-white dark:placeholder:text-zinc-500"
              />

              <input
                type="email"
                placeholder="Email Address"
                className="w-full rounded-xl border border-zinc-300 bg-white px-5 py-4 text-zinc-900 outline-none transition placeholder:text-zinc-400 focus:border-blue-600 dark:border-zinc-700 dark:bg-zinc-950 dark:text-white dark:placeholder:text-zinc-500"
              />

              <input
                type="text"
                placeholder="Subject"
                className="w-full rounded-xl border border-zinc-300 bg-white px-5 py-4 text-zinc-900 outline-none transition placeholder:text-zinc-400 focus:border-blue-600 dark:border-zinc-700 dark:bg-zinc-950 dark:text-white dark:placeholder:text-zinc-500"
              />

              <textarea
                rows={6}
                placeholder="Write your message..."
                className="w-full resize-none rounded-xl border border-zinc-300 bg-white px-5 py-4 text-zinc-900 outline-none transition placeholder:text-zinc-400 focus:border-blue-600 dark:border-zinc-700 dark:bg-zinc-950 dark:text-white dark:placeholder:text-zinc-500"
              />

              <Button className="w-full py-4 text-base">
                Send Message
              </Button>
            </form>
          </motion.div>
        </div>
      </div>
    </section>
  );
}